scan_linter_check.script:
(function(engine) {
    var rule = new global.EcsContext(engine.current).businessRule();
    if (!engine.rootNode || !rule) {
        return;
    }
    var hits = new global.EcsBusinessRule(new global.EcsAst(engine.rootNode), rule).unnecessaryCurrentUpdates();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-BR-001',
        title: 'Unnecessary current.update() in a Business Rule',
        recommendation: 'Remove current.update(). In a before rule, set fields on current and let the save persist ' +
            'them; if the logic must run after the save, move the field changes to a before rule. In a display rule, ' +
            'do not save the record.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
